var i=8;var a=`008-cooking-workflow-and-time-management`;var n=`001`;var o={en:`Cooking Workflow and Time Management`,ua:`Послідовність приготування та керування часом`};var s={short:`Kitchen workflow is the sequence and timing of preparation, heating, resting, and serving. By coordinating active and unattended work, cooks can deliver several components together without sacrificing quality or food safety.`,sections:[{title:`Core idea`,text:`Cooking consists of dependent operations: bread dough must ferment before baking, a pan must heat before searing, and food requiring chilling needs adequate cooling time. These dependencies form a workflow rather than an arbitrary list.`},{title:`Scientific / practical principles`,text:`The longest or least flexible task often determines the schedule. Some steps can run in parallel, but an unattended pan, unsafe cooling, or overloaded workspace creates risk. A task is complete only when its quality and safety checks pass.`},{title:`How to apply it`,text:`Work backward from serving time. Identify active and passive steps, required equipment and critical points; start long operations early, coordinate shared burners, and leave time for resting and cleanup.`},{title:`Practical example`,text:`For roast chicken with rice and salad, start preheating and chicken preparation first, begin rice while the chicken cooks, wash salad vegetables separately, and dress salad near serving time. Check chicken with a thermometer.`},{title:`Common mistakes and limitations`,text:`Poor sequencing causes cold sides, overcooked proteins, or raw vegetables contaminating cooked food. Do not schedule multiple tasks that all require continuous attention during the same few minutes.`},{title:`Additional application`,text:`Separate active work (chopping, stirring, tasting) from passive time (marinating, baking, chilling). Begin the longest dependent task first, schedule safe cooling, and plan a finishing window so each component is ready close to service. A timeline should show tasks that can overlap and tasks that cannot.`}]};var r={short:`Кухонний процес охоплює послідовність і час підготовки, нагрівання, відпочинку та подачі страв. Узгодження активних і пасивних етапів дає змогу вчасно завершити всі компоненти без втрати якості та безпечності.`,sections:[{title:`Суть`,text:`Готування складається із залежних операцій: тісто має піднятися перед випіканням, сковорода має нагрітися перед обсмажуванням, а продукти для зберігання потребують належного охолодження. Це робочий процес, а не довільний список кроків.`},{title:`Наукові та практичні принципи`,text:`Найтриваліша або найменш гнучка операція часто визначає розклад. Частину дій можна виконувати паралельно, але без нагляду за сковородою, правильного охолодження та вільної робочої зони виникають ризики. Завершення етапу перевіряють за якістю й безпечністю.`},{title:`Як застосовувати`,text:`Плануйте у зворотному напрямку від часу подачі. Позначте активні та пасивні операції, потрібний інвентар і критичні точки; довгі процеси починайте першими, узгоджуйте використання конфорок і залишайте час на відпочинок страв та прибирання.`},{title:`Практичний приклад`,text:`Для курки з рисом і салатом спочатку розігрійте духовку та підготуйте птицю, а поки вона печеться, приготуйте рис, окремо помийте овочі, а заправку до салату додайте безпосередньо перед подачею. Готовність курки перевірте термометром.`},{title:`Поширені помилки й обмеження`,text:`Погана послідовність призводить до холодних гарнірів, пересушених білкових продуктів або забруднення готової їжі сирими. Не ставте одночасно надто багато завдань, що вимагають безперервної уваги.`},{title:`Додаткове застосування`,text:`Розділяйте активну роботу (нарізання, помішування, дегустацію) та пасивний час (маринування, запікання, охолодження). Розпочинайте з найдовшого залежного процесу, заплануйте безпечне охолодження й фінальні дії перед подачею. У графіку позначайте, які завдання можна виконувати паралельно, а які можна виконувати лише послідовно.`}]};var l=[3,4,278,279];var c=`References / Джерела`;var d=[`https://www.cacfp.org/2024/05/07/culinary-basics-mise-en-place/`,`https://www.who.int/activities/promoting-safe-food-handling/five-key-to-safer-food/`];var h={id:8,slug:a,group:`001`,title:o,en:s,ua:r,related:l,referenceTitle:c,references:d};export{h as default,s as en,n as group,i as id,c as referenceTitle,d as references,l as related,a as slug,o as title,r as ua};